def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp = [h[1] for h in history]
    me = [h[0] for h in history]

    recent_opp_d = sum(1 for x in opp[-12:] if x == 'D')
    recent_opp_c = 12 - recent_opp_d if n >= 12 else sum(1 for x in opp if x == 'C')
    window = min(n, 12)
    recent_rate = (window - sum(1 for x in opp[-window:] if x == 'D')) / window

    if n >= 2 and (me[-1] == 'D' or opp[-1] == 'D'):
        if me[-2] == 'D' and opp[-2] == 'D' and recent_rate < 0.5:
            return 'C'

    remaining = 100 - n
    if remaining <= 1:
        return 'D'
    if remaining <= 3 and recent_rate < 0.5:
        return 'D'

    total_opp_d = sum(1 for x in opp if x == 'D')
    total_opp_c = n - total_opp_d

    if total_opp_c == 0:
        return 'D'

    if n >= 6 and total_opp_d == 1 and n >= 8:
        bad = 0
        for i in range(n):
            if opp[i] == 'D' and i + 1 < n and opp[i + 1] == 'D':
                bad += 1
        if bad == 0:
            return 'C'

    if n >= 10:
        long_rate = total_opp_c / n
        if long_rate >= 0.95 and total_opp_d <= 1:
            if remaining <= 6:
                return 'C'
            if n % 11 == 0 and n < 90:
                return 'D'
            return 'C'

    if n >= 8 and total_opp_c / n <= 0.15:
        return 'D'

    if recent_rate >= 0.7:
        if opp[-1] == 'D':
            if rng.random() < 0.75:
                return 'D'
            return 'C'
        if n >= 12 and total_opp_d >= 2:
            if n % 13 == 5:
                return 'D'
        return 'C'

    if recent_rate >= 0.4:
        if opp[-1] == 'C':
            if me[-1] == 'D' and rng.random() < 0.5:
                return 'D'
            return 'C'
        if rng.random() < 0.2:
            return 'C'
        return 'D'

    if recent_rate >= 0.2:
        if opp[-1] == 'D':
            if opp[-2] == 'D' if n >= 2 else False:
                if rng.random() < 0.08:
                    return 'C'
                return 'D'
            if rng.random() < 0.35:
                return 'C'
            return 'D'
        return 'C'

    if rng.random() < 0.03:
        return 'C'
    return 'D'
